class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        def pattern(word: str) -> list[int]:
            first_seen = {}
            encoded = []
            for i, ch in enumerate(word):
                if ch not in first_seen:
                    first_seen[ch] = i
                encoded.append(first_seen[ch])
            return encoded

        return pattern(s) == pattern(t)

